 +'<div class="ft">توزيع حصص النشاط (10%) حسب الفصل والبرنامج</div>'+tbl([['الفصل','المجال','البرنامج','حصص الفترة'],...as.map(a=>[a[2],a[3],a[4],a[5]]),['المجموع','','',as.reduce((s,a)=>s+a[5],0)]])
