 const out=[],ms=[],tS=new Set(),cS=new Set(),tD={},cD={},cWk={},cW={},tW={},wT={},tot={},np=new Set();AA.forEach(a=>tot[a[0]]=(tot[a[0]]||0)+a[5]);let fail=0;const wcap=Math.ceil(AA.reduce((s,a)=>s+a[5],0)/W.length)+2;const mx=Math.max(...AA.map(a=>a[5])),inc=(o,k)=>o[k]=(o[k]||0)+1;occRows().forEach(r=>{tS.add(r[3]+'|'+r[0]+'|'+r[1]+'|'+r[2]);cS.add(r[6]+'|'+r[0]+'|'+r[1]+'|'+r[2]);inc(tD,r[3]+'|'+r[0]+'|'+r[1]);inc(cD,r[6]+'|'+r[0]+'|'+r[1])});
