   const c=(sl[t+'|'+cl]||[]).filter(s=>!isOff(w,s[1])&&!tS.has(t+'|'+w+'|'+s[1]+'|'+s[2])&&!cS.has(cl+'|'+w+'|'+s[1]+'|'+s[2])&&(tD[t+'|'+w+'|'+s[1]]||0)<g.maxD&&(cWk[cl+'|'+w]||0)<classWkCap(cl)).sort((x,y)=>((DAYS.indexOf(x[1])+i)%5)-((DAYS.indexOf(y[1])+i)%5)||x[2]-y[2]);
