function tList(){const T=TM(),all=[...names.map((_,i)=>i),...T.cus.map(c=>c.id)],ord=(T.ord||[]).filter(x=>all.includes(x));return ord.concat(all.filter(x=>!ord.includes(x)))}
const tName=id=>{const T=TM();return T.nm[id]||(typeof id==='number'?names[id]:(T.cus.find(c=>c.id===id)||{}).nm)||String(id)},tVis=()=>tList().filter(id=>!TM().hid.includes(id)),tc=id=>TM().cus.find(c=>c.id===id);
function tRen(id,v){TM().nm[id]=v.trim()||undefined;if(!v.trim())delete TM().nm[id];save();go()}
function tMove(id,d){const l=tList(),i=l.indexOf(id),j=i+d;if(j<0||j>=l.length)return;[l[i],l[j]]=[l[j],l[i]];TM().ord=l;save();go()}
