function tAdd(){const T=TM(),nm=$('#tn1').value.trim(),ty=$('#tt1').value;if(!nm){xmsg('اكتب اسم التبويب');return}const id='c'+T.nid++,c={id,nm,ty};
 if(ty==='note')c.txt='';else if(ty==='table'){c.cols=($('#tc1').value||'العمود 1,العمود 2,العمود 3').split(/[,،]/).map(x=>x.trim()).filter(Boolean);c.rows=[c.cols.map(()=>'')]}
 else if(ty==='form')FORMINIT(c);else if(ty==='tasks')c.items=[];else Object.assign(c,{src:$('#ts1').value,f:{t:'',c:'',d:'',s:'',w1:1,w2:18},cols:null,g:''});
 T.cus.push(c);tab=id;save();go()}
function cSet(id,k,v){tc(id)[k]=v;save()}
