function tkWeek(id){const c=tc(id),w=curW();D.log.filter(r=>r[0]===w).forEach(r=>{const d=iso(dt(r[0],r[1])),t='تنفيذ: '+r[5]+' – فصل '+r[6]+' (حصة '+r[2]+')';if(!c.items.some(x=>x.t===t&&x.d===d&&x.w===r[3]))c.items.push({t,w:r[3],d,s:stt(r)==='منفذة'?'منجزة':'لم تبدأ'})});c.items.sort((a,b)=>(a.d||'9').localeCompare(b.d||'9'));save();go()}
