function cHtml(id){const c=tc(id);if(!c)return'';let b;
 if(c.ty==='note')b=(c.txt||'').split('\n').map(l=>'<p>'+esc(l)+'</p>').join('');
 else if(c.ty==='table')b=tbl([c.cols,...c.rows]);
 else if(c.ty==='form')b=tbl([['الحقل','البيانات'],...c.fields.map(f=>[f.l,fvx(f)])])+'<div class="sg">'+c.sigs.map(s=>'<div>'+esc(s)+'<br>التوقيع</div>').join('')+'</div>';
 else if(c.ty==='tasks')b=tbl([['المهمة','المسؤول','الموعد','الحالة','المتبقي'],...c.items.map(x=>[x.t,x.w,x.d?fd(new Date(x.d+'T00:00:00')):'',x.s,tkStat(x)])]);
 else b=tbl(cData(c));return head(c.nm)+b+(c.ty==='form'?'':sign())}
