function subjHours(s){return ((subjList().find(y=>y.s===s)||{ts:[]}).ts).reduce((a,n)=>a+((smOf(n)||[0,0,0])[2]||0)*18,0)}
function fxSubj(s,on){const set=new Set(fxCfg().sel||[]);(subjList().find(x=>x.s===s)||{ts:[]}).ts.forEach(n=>on?set.add(n):set.delete(n));fxCfg().sel=[...set];genFix()}
function subjTable(){const sel=new Set(fxCfg().sel||[]);return'<div class="tw"><table><tr><th>اختيار المادة</th><th>المادة</th><th>المعلمون</th><th>عدد حصص المادة (الفترة)</th><th>10% = 10 × الحصص ÷ 100</th><th>المختار منها</th></tr>'+subjList().map(x=>{const h=subjHours(x.s),q=Math.round(h*10)/100,on=x.ts.filter(n=>sel.has(n)).length;return'<tr><td><input type="checkbox" '+(on===x.ts.length&&on>0?'checked':'')+' onchange="fxSubj(\''+esc(x.s)+'\',this.checked)"></td><td>'+esc(x.s)+'</td><td>'+x.ts.length+'</td><td>'+h+'</td><td><b>'+q+'</b> حصة</td><td>'+on+' / '+x.ts.length+'</td></tr>'}).join('')+'</table></div>'}
function fxSelHtml(){
 const sel=new Set(fxCfg().sel||[]);
 const ts=schoolTeachers();
 const head1='<p class="mu">حدّد المواد التي تُحتسب منها الـ10%، أو حدّد معلمين بعينهم. تُحسب الحصص كما في الشريحة: 10 × عدد حصص المادة ÷ 100، ثم تُضاف حصص حتى يصل كل فصل إلى 3 حصص نشاط أسبوعيًا.</p>';
 const rows=ts.map(n=>{const t=teachers().find(x=>x.n===n)||{s:'',qu:0};const chk=sel.has(n)?'checked':'';return '<tr><td><input type="checkbox" '+chk+' onchange="fxSel(\''+esc(n)+'\',this.checked)"></td><td>'+esc(n)+'</td><td>'+esc(t.s)+'</td><td>'+t.qu+'</td><td>'+(RQ(n)||0)+'</td></tr>'}).join('');
 return head1+'<p class="'+(FXOK?'ok':'er')+'">'+esc(FXMSG||'اختر المواد أو المعلمين لبدء الحساب.')+'</p>'+'<h3>المواد</h3>'+subjTable()+'<h3>المعلمون</h3><div class="bar">'+b5('fxSelAll(true)','تحديد الكل',1)+b5('fxSelAll(false)','إلغاء الكل',1)+'<span class="mu">المحدد: '+sel.size+' من '+ts.length+'</span></div><div class="tw"><table><tr><th>اختيار</th><th>المعلم</th><th>المادة</th><th>النصاب</th><th>سقف 10%</th></tr>'+rows+'</table></div>';
}

/* ===== خريطة ذهنية ورسم بياني لآلية الـ10% ===== */
function mindSvg(){const C={x:320,y:180},nodes=[['1. إدراج حصص الدليل','الحصص الواردة في الدليل'],['2. تحديد المواد','المواد التي تُحتسب منها 10%'],['3. الحساب','10 × حصص المادة ÷ 100'],['4. التحقق','النشاط ≥ 10% من الجدول'],['5. الإضافة','حتى يصل كل فصل إلى حده']];
 const pts=nodes.map((n,i)=>{const a=-Math.PI/2+i*2*Math.PI/5;return{x:C.x+230*Math.cos(a),y:C.y+150*Math.sin(a),n}});
 const lines=pts.map(p=>'<line x1="'+C.x+'" y1="'+C.y+'" x2="'+p.x.toFixed(0)+'" y2="'+p.y.toFixed(0)+'" stroke="#1f4e8c" stroke-width="2"/>').join('');
 const boxes=pts.map(p=>'<g><rect x="'+(p.x-95).toFixed(0)+'" y="'+(p.y-26).toFixed(0)+'" width="190" height="52" rx="10" fill="#e8f1fb" stroke="#1f4e8c"/><text x="'+p.x.toFixed(0)+'" y="'+(p.y-4).toFixed(0)+'" text-anchor="middle" font-size="13" font-weight="700" fill="#17262b">'+esc(p.n[0])+'</text><text x="'+p.x.toFixed(0)+'" y="'+(p.y+14).toFixed(0)+'" text-anchor="middle" font-size="11" fill="#444">'+esc(p.n[1])+'</text></g>').join('');
 return'<div class="card"><h2>الخريطة الذهنية لآلية الـ10%</h2><svg viewBox="0 0 640 360" width="100%" style="max-width:640px;direction:rtl">'+lines+'<circle cx="'+C.x+'" cy="'+C.y+'" r="52" fill="#00796b"/><text x="'+C.x+'" y="'+(C.y+6)+'" text-anchor="middle" font-size="22" font-weight="700" fill="#fff">10%</text>'+boxes+'</svg></div>'}
function barSvg(){const rows=fxStat();if(!rows.length)return'';const max=Math.max(1,...rows.map(r=>Math.max(r[4],+String(r[5]).split('–').pop()||0)));const W=640,H=40,L=90,R=20;let out='';
 rows.forEach((r,i)=>{const y=20+i*H,tgt=r[4],act=+String(r[5]).split('–')[0]||0,sc=(W-L-R)/max,ok=act>=tgt;
  out+='<text x="'+(L-8)+'" y="'+(y+14)+'" text-anchor="end" font-size="13" fill="#17262b">فصل '+r[0]+'</text>';
  out+='<rect x="'+L+'" y="'+y+'" width="'+(tgt*sc).toFixed(0)+'" height="12" fill="#cfd8dc"/><text x="'+(L+tgt*sc+4).toFixed(0)+'" y="'+(y+11)+'" font-size="11" fill="#444">المطلوب '+tgt+'</text>';
  out+='<rect x="'+L+'" y="'+(y+14)+'" width="'+(act*sc).toFixed(0)+'" height="12" fill="'+(ok?'#2e7d32':'#c62828')+'"/><text x="'+(L+act*sc+4).toFixed(0)+'" y="'+(y+25)+'" font-size="11" fill="#444">المجدول '+act+'</text>'});
 return'<div class="card"><h2>رسم بياني: المطلوب مقابل المجدول لكل فصل (أسبوعيًا)</h2><svg viewBox="0 0 '+W+' '+(40+rows.length*H)+'" width="100%" style="max-width:'+W+'px;direction:ltr">'+out+'</svg><p class="mu">الرمادي = المطلوب، الأخضر = مكتمل، الأحمر = ناقص.</p></div>'}


