function planRow(r){const prog=r.C,g=+r.I||0,rows=D.log.filter(x=>x[5]===prog&&x[8]!==2),n=rows.length,wk=rows.map(x=>x[0]),mn=wk.length?Math.min(...wk):'',mx2=wk.length?Math.max(...wk):'',ok=n>=g&&g>0;return{prog,dom:r.B,goal:r.D,acts:r.E,cls:r.F,resp:r.G,sup:r.H,guide:g,cnt:n,from:mn,to:mx2,pct:g?Math.round(Math.min(n,g)/g*100):0,ind:r.O,tgt:r.P,src:r.S,ref:r.T,ok}}
function planSummaryCard(){const rs=PLAN.mx.map(planRow),done=rs.filter(r=>r.ok).length,g=rs.reduce((a,r)=>a+r.guide,0),c=rs.reduce((a,r)=>a+Math.min(r.cnt,r.guide),0);
 return'<div class="card"><h2>الخطة التشغيلية 1448 – التقدم حسب البرامج</h2><div class="kp"><div><b>'+done+' / '+rs.length+'</b><span>برامج اكتملت حصصها</span></div><div><b>'+c+' / '+g+'</b><span>حصص الدليل المتحققة</span></div><div><b>'+(g?Math.round(c/g*100):0)+'%</b><span>نسبة تحقق الخطة</span></div></div><p class="mu">التفاصيل في تبويب «الخطة التشغيلية».</p></div>'}
function tblRows(rows,maxc){return'<div class="tw"><table>'+rows.map((r,i)=>'<tr>'+r.slice(0,maxc||99).filter((c,j)=>c!==''||j<2).map(c=>i?'<td style="text-align:start">'+esc(c)+'</td>':'<th>'+esc(c)+'</th>').join('')+'</tr>').join('')+'</table></div>'}
function planView(){const rs=PLAN.mx.map(planRow);
 const mxRows=[['م','المجال','البرنامج','الهدف من البرنامج','الفئة المستهدفة','مسؤول التنفيذ','حصص الدليل','المخطط (السجل)','من أسبوع','إلى أسبوع','المتحقق','المؤشر','المستهدف','مصدر التحقق']].concat(PLAN.mx.map((r,i)=>{const p=rs[i];return[r.A,r.B,r.C,r.D,r.F,r.G,String(p.guide),String(p.cnt),String(p.from),String(p.to),p.pct+'%',r.O,r.P,r.S]}));
 const tbl=mxRows.map((r,i)=>'<tr>'+r.map((c,j)=>i?'<td'+(j===10?' class="'+(parseInt(c)>=100?'ok':'wa')+'"':'')+'>'+(j===2?'<b>'+esc(c)+'</b>':esc(c))+'</td>':'<th>'+esc(c)+'</th>').join('')+'</tr>').join('');
 return head('الخطة التشغيلية للنشاط الطلابي – الفصل الأول 1448هـ')
 +'<div class="card"><h2>الهدف العام والأهداف التفصيلية</h2>'+tblRows(PLAN.obj)+'</div>'
 +'<div class="card"><h2>مصفوفة البرامج (المحدثة)</h2><p class="mu">«المخطط (السجل)» و«من/إلى أسبوع» و«المتحقق» تُحسب مباشرة من سجل الحصص الحالي، فأي تعديل في الجدول ينعكس هنا.</p><div class="tw"><table>'+tbl+'</table></div></div>'
 +'<div class="card"><h2>مؤشرات الأداء</h2>'+tblRows(PLAN.ind)+'</div>'
 +'<div class="card"><h2>الأيام والمناسبات (1448)</h2>'+tblRows(PLAN.days)+'</div>'
 +'<div class="card"><h2>الإعدادات</h2>'+planSettRows()+'<div class="bar">'+b5("setStart('2026-08-23')",'اعتماد بداية الفصل 23/8/2026 من الخطة',1)+'</div><p class="mu">الخطة تفترض 23/8/2026، وأداتك تستخدم 30/8/2026 (منطقة غربية). اختر ما يناسبك.</p></div>'
 +'<div class="card"><h2>المرجعية والطريقة</h2>'+tblRows(PLAN.ref)+'</div>';}
