function cfTotals(){const c=cfS();const s1=CV1.slice(0,5).reduce((a,[,m],i)=>a+(+c.s1[i]||0),0);const s2=CV2.reduce((a,[,w],i)=>a+((c.s2[i]||0)/3*w),0);const g=gateInfo();let cls='—';if(!g.ok)cls='غير ممتثلة – بوابة حرجة';else if(s2>=90)cls='امتثال متقدم';else if(s2>=75)cls='امتثال جيد';else if(s2>=60)cls='امتثال يحتاج إلى تحسين';else cls='امتثال منخفض';return{s1,s2:Math.round(s2*10)/10,cls}}
function cfInputs(){const c=cfS(),T=cfTotals(),g=gateInfo();
 return'<div class="card"><h2>بيانات الزيارة</h2><div class="bar"><label>التاريخ <input type="date" value="'+esc(c.v.date)+'" onchange="cfSet(\'v\',\'date\',this.value)"></label><label>نوع الزيارة <select onchange="cfSet(\'v\',\'type\',this.value)"><option'+(c.v.type==='حضورية'?' selected':'')+'>حضورية</option><option'+(c.v.type==='عن بعد'?' selected':'')+'>عن بعد</option></select></label><label>رقم الزيارة <input value="'+esc(c.v.no)+'" onchange="cfSet(\'v\',\'no\',this.value)"></label><label>فترة المتابعة <select onchange="cfSet(\'v\',\'period\',this.value)">'+['الأولى','الثانية','الثالثة','تحقق معالجة'].map(x=>'<option'+(c.v.period===x?' selected':'')+'>'+x+'</option>').join('')+'</select></label></div><p class="mu">بيانات المدرسة وقائد المدرسة والرائد تؤخذ من الإعدادات تلقائيًا.</p></div>'
 +'<div class="card"><h2>أولًا: استمارة المتابعة السريعة (2 = مستوفٍ، 1 = جزئي، 0 = غير مستوفٍ)</h2><div class="tw"><table><tr><th>م</th><th>البند</th><th>الدرجة (0–2)</th></tr>'+CV1.slice(0,5).map(([l],i)=>'<tr><td>'+(i+1)+'</td><td style="text-align:start">'+esc(l)+'</td><td><input type="number" min="0" max="2" style="width:70px" value="'+(c.s1[i]||0)+'" onchange="cfSet(\'s1\','+i+',this.value)"></td></tr>').join('')+'<tr><td>6</td><td>مجموع الدرجات من 10</td><td><b>'+T.s1+'</b></td></tr></table></div></div>'
 +'<div class="card"><h2>التحقق من النسبة النظامية (البوابة)</h2><p>متوسط حصص النشاط الأسبوعية: <b>'+g.act+'</b> من إجمالي الحصص الأسبوعية <b>'+g.weekly+'</b> = <b>'+g.pct+'%</b> — '+(g.ok?'<span class="ok">تحققت النسبة ✔</span>':'<span class="er">لم تتحقق 10% — غير ممتثلة</span>')+'</p></div>'
 +'<div class="card"><h2>ثانيًا: بطاقة التقييم التفصيلية (0–3)</h2><div class="tw"><table><tr><th>م</th><th>المؤشر</th><th>الوزن</th><th>الدرجة (0–3)</th><th>المحسوب</th></tr>'+CV2.map(([l,w],i)=>'<tr><td>'+(i+1)+'</td><td style="text-align:start">'+esc(l)+'</td><td>'+w+'</td><td><input type="number" min="0" max="3" style="width:60px" value="'+(c.s2[i]||0)+'" onchange="cfSet(\'s2\','+i+',this.value)"></td><td>'+Math.round((c.s2[i]||0)/3*w*10)/10+'</td></tr>').join('')+'<tr><td colspan="4"><b>الدرجة الكلية من 100</b></td><td><b>'+T.s2+'</b></td></tr></table></div><p class="mu">درجة البند = (الدرجة ÷ 3) × الوزن. إذا لم تتحقق البوابة تُعد المدرسة غير ممتثلة مهما كانت الدرجة.</p><p><b>التصنيف: '+T.cls+'</b></p></div>'
 +'<div class="card"><h2>خامسًا: خطة المعالجة والتحسين</h2><div class="tw"><table><tr><th>الملاحظة / الفجوة</th><th>السبب الجذري</th><th>الإجراء التصحيحي</th><th>المسؤول</th><th>الموعد</th><th>دليل الإغلاق</th></tr>'+[0,1,2].map(i=>{const r=(c.plan||[])[i]||{};return'<tr>'+['g','c','a','o','d','e'].map(k=>'<td><input style="width:100%" value="'+esc(r[k]||'')+'" onchange="cfSet(\'plan\',['+i+',\''+k+'\'],this.value)"></td>').join('')+'</tr>'}).join('')+'</table></div></div>'
 +'<div class="card"><h2>سادسًا: قياس التحسن بين فترات المتابعة</h2><div class="tw"><table><tr><th>المؤشر</th><th>الفترة السابقة</th><th>الفترة الحالية</th><th>الحكم</th></tr>'+['الدرجة الكلية','نسبة تخصيص 10%','نسبة إغلاق الملاحظات','متوسط زمن المعالجة','عدد الملاحظات المكررة'].map((l,i)=>'<tr><td>'+l+'</td><td><input value="'+esc((c.imp[i]||{}).p||'')+'" onchange="cfSet(\'imp\',['+i+',\'p\'],this.value)"></td><td><input value="'+esc((c.imp[i]||{}).c||'')+'" onchange="cfSet(\'imp\',['+i+',\'c\'],this.value)"></td><td><select onchange="cfSet(\'imp\',['+i+',\'j\'],this.value)">'+['تحسن','ثبات','تراجع'].map(x=>'<option'+((c.imp[i]||{}).j===x?' selected':'')+'>'+x+'</option>').join('')+'</select></td></tr>').join('')+'</table></div></div>'
 +'<div class="card"><h2>سابعًا: الخلاصة والتوصية</h2><div class="bar"><label style="flex:1">أبرز نقاط القوة<br><textarea style="width:100%" onchange="cfSet(\'v\',\'str\',this.value)">'+esc(c.v.str||'')+'</textarea></label><label style="flex:1">أبرز فجوة ذات أولوية<br><textarea style="width:100%" onchange="cfSet(\'v\',\'gap\',this.value)">'+esc(c.v.gap||'')+'</textarea></label></div><div class="bar"><label style="flex:1">التوصية وموعد التحقق<br><textarea style="width:100%" onchange="cfSet(\'v\',\'rec\',this.value)">'+esc(c.v.rec||'')+'</textarea></label></div></div>'
 +'<div class="card"><div class="bar">'+b5('cfPrint()','طباعة الاستمارة بالشكل الرسمي',0)+b5("outDo(cfHtml(),'w','compliance-form')",'Word',1)+b5("outDo(cfHtml(),'f','compliance-form')",'PDF',1)+'</div></div>'}
function cfHtml(){const c=cfS(),T=cfTotals(),g=gateInfo(),sc=(c.school||S.school||'');
 return head('استمارة متابعة حوكمة الأداء والامتثال في الأنشطة الطلابية')
 +'<p style="text-align:center">أداة تحقق ميداني لقياس الامتثال وجودة التنفيذ والأثر</p>'
 +tbl([['البيان','القيمة'],['اسم المدرسة',S.school||''],['اسم قائد المدرسة',S.principal||''],['اسم رائد/ة النشاط',S.leader||''],['تاريخ الزيارة / نوعها',(c.v.date||'')+' – '+(c.v.type||'')],['رقم الزيارة',c.v.no||''],['فترة المتابعة',c.v.period||'']])
 +'<div class="ft">أولًا: المتابعة السريعة</div>'+tbl([['م','البند','الدرجة (0–2)'],...CV1.slice(0,5).map(([l],i)=>[String(i+1),l,String(c.s1[i]||0)]),['6','مجموع الدرجات من 10',String(T.s1)]])
 +'<div class="ft">التحقق من النسبة النظامية</div><p>إجمالي الحصص الأسبوعية: '+g.weekly+' · حصص النشاط المنفذة/المخصصة (متوسط أسبوعي): '+g.act+' · النسبة: '+g.pct+'% · '+(g.ok?'تحققت':'لم تتحقق 10%')+'</p>'
 +'<div class="ft">ثانيًا: بطاقة التقييم التفصيلية</div>'+tbl([['م','المؤشر','الوزن','الدرجة 0–3','المحسوب'],...CV2.map(([l,w],i)=>[String(i+1),l,String(w),String(c.s2[i]||0),String(Math.round((c.s2[i]||0)/3*w*10)/10)]),['','الدرجة الكلية من 100','100','',String(T.s2)]])+'<p><b>التصنيف: '+T.cls+'</b></p>'
 +'<div class="ft">خامسًا: خطة المعالجة والتحسين</div>'+tbl([['الملاحظة / الفجوة','السبب الجذري','الإجراء التصحيحي','المسؤول','الموعد','دليل الإغلاق'],...[0,1,2].map(i=>{const r=(c.plan||[])[i]||{};return[r.g||'',r.c||'',r.a||'',r.o||'',r.d||'',r.e||'']})])
 +'<div class="ft">سادسًا: قياس التحسن</div>'+tbl([['المؤشر','السابقة','الحالية','الحكم'],...['الدرجة الكلية','نسبة تخصيص 10%','نسبة إغلاق الملاحظات','متوسط زمن المعالجة','عدد الملاحظات المكررة'].map((l,i)=>[l,(c.imp[i]||{}).p||'',(c.imp[i]||{}).c||'',(c.imp[i]||{}).j||''])])
 +'<div class="ft">سابعًا: الخلاصة والتوصية</div>'+tbl([['نقاط القوة','أبرز فجوة','التوصية وموعد التحقق'],[c.v.str||'',c.v.gap||'',c.v.rec||'']])
 +'<div class="sg"><div>اسم قائد/ة المدرسة والتوقيع<br>............</div><div>اسم المتابع/ة والتوقيع<br>............</div><div>اعتماد الجهة المختصة<br>............</div></div>'}
