 return '<h3>الأسبوع '+w+' ('+esc(dt(w,'الأحد').toLocaleDateString('ar-SA-u-ca-gregory',{day:'numeric',month:'numeric'}))+' – '+esc(dt(w,'الخميس').toLocaleDateString('ar-SA-u-ca-gregory',{day:'numeric',month:'numeric'}))+')</h3>'
