function compsHtml(){return head('المسابقات الطالبية المعتمدة 1448هـ')+tbl([['المجال','المسابقة','المرحلة','الصفوف','المستوى','نوع المشاركة','الجهة المنظمة','التاريخ'],...APPROVED.map(a=>[a[0],a[1],a[2],a[3],a[4],a[5],a[6],a[7]])])+sign()}
