function compSelAll(){const rows=APPROVED.filter(a=>!CPF.d||a[0]===CPF.d);S.compSel=[...new Set([...(S.compSel||[]),...rows.map(a=>a[1])])];save();go()}
function compSync(){const sel=new Set(S.compSel||[]);S.comp=S.comp||[];let n=0;APPROVED.filter(a=>sel.has(a[1])).forEach(a=>{if(!S.comp.some(c=>c.n===a[1])){S.comp.push({n:a[1],d:a[7],l:a[4],t:'',c:'',s:'مخطط',r:''});n++}});auditLog('إدراج '+n+' مسابقة معتمدة في السجل');save();xmsg('أُدرجت '+n+' مسابقة في سجل المسابقات');go()}
{const w0=warnings;warnings=function(){const W=w0();(S.comp||[]).forEach(c=>{if(!APPROVED.some(a=>a[1]===c.n))W.push(['اعتماد','المسابقة «'+c.n+'» غير واردة في المسابقات المعتمدة من المركز'])});return W}}
