function m10Calc(){const g=gateInfo(),L=subjLedger(),wk=D.G.length,placedW=g.act,quotaSub=L.reduce((a,x)=>a+x.q,0),placedSub=L.reduce((a,x)=>a+x.pl,0),hoursSub=L.reduce((a,x)=>a+x.h,0);
 return{wk,placedW,pctW:g.pct,okW:g.ok,need10W:Math.round(wk*10)/100,hoursSub:Math.round(hoursSub),quotaSub:Math.round(quotaSub*10)/10,placedSub,pctSub:quotaSub?Math.round(placedSub/quotaSub*1000)/10:0,okSub:placedSub>=quotaSub*0.999,L}}
