 +'<tr><td>أساس الحساب</td><td style="text-align:start">إجمالي الحصص الأسبوعية في الجدول</td><td style="text-align:start">مجموع حصص كل مادة في العام</td></tr>'
 +'<tr><td>المقدار الأساسي</td><td>'+c.wk+' حصة أسبوعيًا</td><td>'+c.hoursSub+' حصة في الفترة</td></tr>'
 +'<tr><td>المطلوب (10%)</td><td>'+c.need10W+' حصة أسبوعيًا</td><td>'+c.quotaSub+' حصة في الفترة</td></tr>'
 +'<tr><td>المنفذ/المخصص فعليًا</td><td>'+c.placedW+' حصة أسبوعيًا ('+c.pctW+'%)</td><td>'+c.placedSub+' حصة ('+c.pctSub+'%)</td></tr>'
 +'<tr><td>النتيجة</td><td class="'+(c.okW?'ok':'er')+'">'+(c.okW?'تحققت 10%':'لم تتحقق 10%')+'</td><td class="'+(c.okSub?'ok':'er')+'">'+(c.okSub?'تحققت 10%':'لم تتحقق 10%')+'</td></tr>'
