 +'<div class="card"><h2>تفصيل المواد (طريقة التعميم)</h2><div class="tw"><table><tr><th>المادة</th><th>حصص المادة</th><th>10%</th><th>المستثمر</th><th>المتبقي</th></tr>'+c.L.map(x=>'<tr><td>'+esc(x.s)+'</td><td>'+x.h+'</td><td>'+x.q+'</td><td>'+x.pl+'</td><td class="'+(x.rem>0.5?'wa':'ok')+'">'+(Math.round(x.rem*10)/10)+'</td></tr>').join('')+'</table></div></div>'
