/* ===== مؤشر المسابقات في لوحة المؤشرات: لكل المجالات الخمسة + المؤشر العام ===== */
function compIndicatorCard(){const sel=new Set(S.compSel||[]),logged=new Set((S.comp||[]).map(c=>c.n)),cards=S.cards||{};
 const filledOf=n=>{const st=cards[n]||{};return Object.keys(st).some(k=>String(st[k]).trim()!=='')};
 const rows=APPROVED_DOMAINS.map(d=>{const L=APPROVED.filter(a=>a[0]===d);return[d,L.length,L.filter(a=>sel.has(a[1])).length,L.filter(a=>logged.has(a[1])).length,L.filter(a=>filledOf(a[1])).length]});
 const tot=rows.reduce((a,r)=>[a[0]+r[1],a[1]+r[2],a[2]+r[3],a[3]+r[4]],[0,0,0,0]);
 return'<div class="card"><h2>المسابقات الطالبية المعتمدة – المؤشر</h2><div class="kp"><div><b>'+tot[0]+'</b><span>مسابقة معتمدة (المؤشر العام)</span></div><div><b>'+tot[1]+'</b><span>مختارة للخطة</span></div><div><b>'+tot[2]+'</b><span>مدرجة في السجل</span></div><div><b>'+tot[3]+'</b><span>لها بطاقة تنفيذ</span></div></div>'
 +'<div class="tw"><table><tr><th>المجال</th><th>معتمدة</th><th>مختارة</th><th>في السجل</th><th>لها بطاقة</th></tr>'+rows.map(r=>'<tr><td style="text-align:start">'+esc(r[0])+'</td><td>'+r[1]+'</td><td>'+r[2]+'</td><td>'+r[3]+'</td><td>'+r[4]+'</td></tr>').join('')+'<tr><td><b>الإجمالي</b></td><td><b>'+tot[0]+'</b></td><td><b>'+tot[1]+'</b></td><td><b>'+tot[2]+'</b></td><td><b>'+tot[3]+'</b></td></tr></table></div></div>'}
{const v0c=views[0];views[0]=function(){return v0c()+compIndicatorCard()}}

