function cardDayName(d){if(!d)return'';const x=new Date(d+'T00:00:00');return DAYS[x.getDay()-0]||''}
function cardWeek(d){if(!d)return'';const x=new Date(d+'T00:00:00');const diff=Math.floor((x-START)/864e5);const w=Math.floor(diff/7)+1;return(w>=1&&w<=18)?String(w):'خارج الفصل'}
