/* ===== تاريخ بداية الفصل في الخطة التشغيلية: يتزامن مع الإعدادات ===== */
function planSettRows(){const live='<div class="bar"><label>تاريخ بداية الفصل (مرتبط بالإعدادات) <input type="date" value="'+esc(S.start||'')+'" onchange="setStart(this.value)"></label></div>';const rows=PLAN.sett.filter(r=>!/بداية الفصل/.test(r[0]||''));return live+tblRows(rows)}

try{const __sv=JSON.parse(localStorage.getItem('act1448')||'null');if(__sv){S=Object.assign(S,__sv);if(!__sv.asg)delete S.asg;applyState()}}catch(e){}
go();
(async()=>{try{if(!window.claude)return;const db=await claude.use('db');if(!db)return;ref=db.doc('app/state');const s=await ref.get();if(s.exists&&!DIRTY){S=Object.assign(S,s.data());applyMerge();if(S.G&&S.G.length){D.G=S.G;_GS=null}if(S.ren)applyRen();if(S.log)D.log=S.log;if(S.T)D.T=S.T.filter(t=>t[0]!=='الإجمالي');if(S.P)D.P=S.P.filter(p=>p[1]!=='None');if(S.start)START=new Date(S.start+'T00:00:00');calReset();quotaApply();if(!S.school)S.school='ثانوية أبي طلحة الأنصاري';if(asgN()&&S.autoSync!==false)syncLog();go()}}catch(e){}})();

const GROUPS=[['النصاب والتوزيع',[1,8,17,18,19,21,24,32]],['التقارير والتصدير',[7,9,10,14]],['المناسبات والمسابقات',[2,12,29]],['المتابعة والحضور',[4,25,26,27,28]],['الإعدادات',[5,15,16]]];
let GRP_SEL={};
function groupView(gi){const g=GROUPS[gi];const cur=(GRP_SEL[gi]!==undefined)?GRP_SEL[gi]:g[1][0];
 const sel='<div class="bar"><label>القسم <select onchange="GRP_SEL['+gi+']=+this.value;go()">'+g[1].map(id=>'<option value="'+id+'"'+(id===cur?' selected':'')+'>'+esc(names[id]||('قسم '+id))+'</option>').join('')+'</select></label></div>';
 return sel+views[cur]();}
/* تبويبات مخفية من القوائم (ما زال كودها محفوظًا ويمكن إعادتها) */
const HIDDEN_FROM_MENU=['مقارنة الـ10%','الإصدار الشامل','الإشعارات والتقارير','الواتساب'];
GROUPS.forEach(g=>{g[1]=g[1].filter(id=>!HIDDEN_FROM_MENU.includes(names[id]))});
GROUPS.forEach((g,gi)=>{views.push(()=>groupView(gi));names.push(g[0])});
(function(){const T=TM();const hide=new Set(T.hid||[]);GROUPS.forEach(g=>g[1].forEach(id=>hide.add(id)));
HIDDEN_FROM_MENU.forEach(n=>{const i=names.indexOf(n);if(i>=0)hide.add(i)});T.hid=[...hide];save()})();
try{go()}catch(e){}


/* ===== تبويب المسابقات: أداة مستقلة تُعرض داخل إطار حتى لا تتعارض مع تنسيق الأداة ===== */
views.push(function(){return '<div class="card"><h2>إدارة المسابقات الطلابية</h2><p class="mu">أداة مستقلة لإدارة المسابقات والجوائز والشهادات، تعمل داخل هذا التبويب.</p><iframe src="competitions.html" title="إدارة المسابقات" style="width:100%;height:78vh;min-height:520px;border:1px solid var(--bd);border-radius:12px;background:#fff"></iframe></div>'});
names.push('إدارة المسابقات');
try{go()}catch(e){}

/* ===== توحيد بيانات المدرسة مع أداة المسابقات ===== */
(function(){try{const sh=JSON.parse(localStorage.getItem('schoolShared_v1')||'null');if(sh){if(sh.schoolName)S.school=sh.schoolName;if(sh.principalName)S.principal=sh.principalName;if(sh.coordinatorName)S.leader=sh.coordinatorName}}catch(e){}})();

/* طباعة جدول العام على دفعات من 6 أسابيع: كل دفعة تحمل أسماء كل المعلمين وبخط مقروء */
function gridPrintAll(){const f=YW.f||1,t=YW.t||18;let out='';
 for(let s=Math.max(1,f);s<=Math.min(18,t);s+=6){YW.f=s;YW.t=Math.min(t,s+5,18);const html=yearForm();
  const tmp=document.createElement('div');tmp.style.cssText='position:absolute;left:-99999px;top:0;width:1040px;background:#fff';tmp.innerHTML=html;document.body.appendChild(tmp);
  const h=tmp.scrollHeight||600;tmp.remove();const z=Math.min(1,Math.max(.5,620/h));
  const th=html.replace('<table style="font-size:11px"><tr>','<table style="font-size:11px"><thead><tr>').replace('</tr>','</tr></thead><tbody>').replace('</table>','</tbody></table>');
  out+='<div style="page-break-after:always;zoom:'+z.toFixed(2)+'">'+th+'</div>'}
 YW.f=f;YW.t=t;pr(out)}
